package com.ollie.tierborne.client;
import com.ollie.tierborne.Tierborne;import com.ollie.tierborne.entity.ModEntities;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.client.event.EntityRenderersEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=Tierborne.MOD_ID,bus=Mod.EventBusSubscriber.Bus.MOD,value=Dist.CLIENT) public final class ClientModEvents{private ClientModEvents(){}@SubscribeEvent public static void registerRenderers(EntityRenderersEvent.RegisterRenderers event){event.registerEntityRenderer(ModEntities.FIREBALL.get(),FireballRenderer::new);event.registerEntityRenderer(ModEntities.FLAME_SLASH.get(),FlameSlashRenderer::new);}}
